let alternateUploadBusy=false;
function renderAlternateUpload(song){
  const form=$("#alternateUploadForm");
  $("#alternateUploadContext").textContent=`Creates a new alternate version of “${song.title}” by ${song.artistName}.`;
  if($("#alternateSongId").value===song.id)return;
  form.reset();
  delete form.dataset.versionId;
  $("#alternateVersionTitle").readOnly=false;
  setValue("#alternateSongId",song.id);
  if(!alternateUploadBusy)alternateUploadUi.idle();
}
async function uploadAlternateVersion(event){
  event.preventDefault();
  if(alternateUploadBusy)return;
  const form=event.currentTarget;
  const songId=$("#alternateSongId").value;
  const song=state.songs.find(item=>item.id===songId);
  const label=$("#alternateVersionTitle").value.trim();
  const file=$("#alternateAudioFile").files?.[0];
  const problem=!state.authenticated||!song?"Select a song you own first.":!label?"Add a version title.":!file?"Choose an audio file first.":!file.size?"Choose a non-empty audio file.":audioFileProblem(file);
  if(problem){alternateUploadUi.fail(problem);return}
  const versionId=form.dataset.versionId||crypto.randomUUID();
  form.dataset.versionId=versionId;
  $("#alternateVersionTitle").readOnly=true;
  alternateUploadBusy=true;
  const controls=[...form.querySelectorAll("input:not([type=hidden]),button")];
  controls.forEach(control=>control.disabled=true);
  $("#uploadAlternateButton").textContent="Uploading…";
  alternateUploadUi.start(`Preparing alternate version for “${song.title}”…`);
  try{
    await api({action:"create_alternate_version",songId,versionId,label});
    await uploadAudioToVersion({file,songId,versionId,ui:alternateUploadUi});
    if($("#alternateSongId").value===songId){form.reset();setValue("#alternateSongId",songId);delete form.dataset.versionId;$("#alternateVersionTitle").readOnly=false}
    alternateUploadUi.success(`“${label}” uploaded as an alternate version of “${song.title}”.`,true);
  }catch(error){
    alternateUploadUi.fail(`Upload incomplete for “${song.title}”: ${error.message} Retry here, or open the new version in the list to finish uploading.`);
  }finally{
    alternateUploadBusy=false;
    controls.forEach(control=>control.disabled=false);
    $("#uploadAlternateButton").textContent="Upload alternate version";
  }
  await loadCatalog(state.selectedId);
}
