document.querySelectorAll("[data-close]").forEach(button=>button.addEventListener("click",()=>button.closest("dialog").close()));
document.querySelectorAll("dialog").forEach(dialog=>dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close()}));
$("#newSongForm").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const submit=form.querySelector('button[type="submit"]');const masterFile=$("#newMasterFile").files?.[0]||null;const problem=masterFile?masterFileProblem(masterFile):"";if(problem){uploadUi.masterCopy.fail(problem);message(problem);return}submit.disabled=true;try{const data=await api({action:"create_song",artistName:$("#newArtistName").value,title:$("#newTitle").value,genre:$("#newGenre").value,salePriceCents:Math.round(Number($("#newSalePrice").value||0)*100)});let note=data.message;if(masterFile){const masterVersionId=data.masterVersionId||data.versionIds?.sale_master;try{if(!masterVersionId)throw new Error("the sale master version was not provisioned");await uploadMasterToVersion({file:masterFile,songId:data.songId,versionId:masterVersionId,ui:uploadUi.masterCopy});note=`${data.message}. Master copy saved to the sale master.`}catch(error){note=`Song created, but the master copy did not upload (${error.message}). Open the Sale master version to retry.`}}elements.songDialog.close();form.reset();uploadUi.masterCopy.idle();message(note);await loadCatalog(data.songId)}catch(error){message(error.message)}finally{submit.disabled=false}});
$("#newMasterFile").addEventListener("change",event=>{const file=event.currentTarget.files?.[0];if(!file){uploadUi.masterCopy.idle();return}const problem=masterFileProblem(file);problem?uploadUi.masterCopy.fail(problem):uploadUi.masterCopy.idle(uploadReadyLabel(file))});
$("#songForm").addEventListener("submit",async event=>{event.preventDefault();const driveInput=$("#googleDriveUrl");const driveButton=$("#saveDriveUrlButton");const googleDriveUrl=driveLinkHref(driveInput.value);if(driveInput.value.trim()&&!googleDriveUrl){renderDriveLink();message("Paste a shareable https://drive.google.com link for the master");driveInput.focus();return}const savingDriveLink=event.submitter===driveButton;if(savingDriveLink)driveButton.disabled=true;try{const data=await api({action:"save_song",googleDriveUrl,songId:$("#songId").value,artistName:$("#artistName").value,title:$("#title").value,albumTitle:$("#albumTitle").value,genre:$("#genre").value,isrc:$("#isrc").value,upc:$("#upc").value,rightsStatus:$("#rightsStatus").value,saleStatus:$("#saleStatus").value,salePriceCents:Math.round(Number($("#salePrice").value||0)*100),explicitLyrics:$("#explicitLyrics").checked,notes:$("#songNotes").value,lyricsText:$("#lyricsText").value});message(data.message);await loadCatalog(data.songId);if(savingDriveLink)markDriveLinkSaved()}catch(error){message(error.message)}finally{driveButton.disabled=false}});
$("#googleDriveUrl").addEventListener("input",renderDriveLink);
$("#pushToShopButton").addEventListener("click",pushToShop);
$("#versionTable").addEventListener("click",event=>{const button=event.target.closest("[data-version-id]");if(button)openVersion(button.dataset.versionId)});
$("#radioQueue").addEventListener("click",event=>{const button=event.target.closest("[data-queue-version]");if(button)openVersion(button.dataset.queueVersion,button.dataset.queueSong)});
$("#audioFile").addEventListener("change",()=>{const file=$("#audioFile").files?.[0];uploadUi.audio.idle(file?uploadReadyLabel(file):"No file selected.")});
$("#uploadAudioButton").addEventListener("click",uploadVersionAudio);
$("#deleteVersionAudioButton").addEventListener("click",deleteVersionAudio);
$("#versionVideoFile").addEventListener("change",()=>{const file=$("#versionVideoFile").files?.[0];const status=$("#versionVideoState");if(status)status.textContent=file?uploadReadyLabel(file):"No version video linked yet."});
$("#uploadVersionVideoButton").addEventListener("click",uploadVersionVideo);
async function loadRadioPickerTracks(){const list=$("#radioPickerList");list.innerHTML='<p class="radio-picker-loading">Loading your radio tracks…</p>';list.hidden=false;try{const data=await audioApi({method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"list_radio_tracks"})});if(!data.tracks?.length){list.innerHTML='<p class="radio-picker-empty">No radio tracks found. Upload a track to HALO Radio first, then come back here to import it.</p>';return}list.innerHTML=data.tracks.map(track=>`<button class="radio-picker-track" type="button" data-radio-track-id="${escapeHtml(track.id)}" data-radio-track-title="${escapeHtml(track.title)}"><strong>${escapeHtml(track.title)}</strong><small>${escapeHtml(track.artist)}${track.filename?" · "+escapeHtml(track.filename):""}</small></button>`).join("")}catch(error){list.innerHTML=`<p class="radio-picker-error">${escapeHtml(error.message)}</p>`}}
async function importRadioTrack(radioTrackId,radioTrackTitle){const songId=$("#versionSongId").value;const versionId=$("#versionId").value;if(!songId||!versionId||!radioTrackId)return;$("#radioPickerList").hidden=true;uploadUi.audio.start(`Importing "${radioTrackTitle}" from Radio…`);try{const data=await audioApi({method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"import_from_radio",songId,versionId,radioTrackId})});uploadUi.audio.success("Radio track imported and connected.",true);message(data.message);await loadCatalog(songId);openVersion(versionId,songId)}catch(error){uploadUi.audio.fail(error.message);message(error.message)}}
$("#importFromRadioButton").addEventListener("click",()=>{const list=$("#radioPickerList");if(!list.hidden){list.hidden=true;return}loadRadioPickerTracks()});
$("#radioPickerList").addEventListener("click",event=>{const btn=event.target.closest("[data-radio-track-id]");if(btn)importRadioTrack(btn.dataset.radioTrackId,btn.dataset.radioTrackTitle)});
$("#uploadArtworkButton").addEventListener("click",uploadArtwork);
$("#deleteArtworkButton").addEventListener("click",deleteArtwork);
$("#artworkFile").addEventListener("change",()=>{const file=$("#artworkFile").files?.[0];uploadUi.artwork.idle(file?uploadReadyLabel(file):"No file selected.")});
$("#versionArtworkFile").addEventListener("change",()=>{const file=$("#versionArtworkFile").files?.[0];uploadUi.versionArtwork.idle(file?uploadReadyLabel(file):"No file selected.")});
$("#uploadVersionArtworkButton").addEventListener("click",uploadVersionArtwork);
$("#deleteVersionArtworkButton").addEventListener("click",deleteVersionArtwork);

$("#versionForm").addEventListener("submit",async event=>{event.preventDefault();try{const data=await api({action:"save_version",songId:$("#versionSongId").value,versionId:$("#versionId").value,versionType:$("#versionType").value,label:$("#versionLabel").value,masteringStatus:$("#masteringStatus").value,audioUrl:$("#audioUrl").value,videoUrl:$("#versionVideoUrl").value,promoVideoUrl:$("#promoVideoUrl").value,durationSeconds:$("#durationSeconds").value,targetLufs:$("#targetLufs").value,truePeakDbtp:$("#truePeakDbtp").value,cleanLyrics:$("#cleanLyrics").checked,saleEnabled:$("#saleEnabled").checked,notes:$("#versionNotes").value});elements.versionDialog.close();message(data.message);await loadCatalog(data.songId)}catch(error){message(error.message)}});
$("#reviewButton").addEventListener("click",async()=>{const song=selectedSong();if(!song)return;try{const data=await api({action:"review_song",songId:song.id});message(data.message);await loadCatalog(song.id)}catch(error){message(error.message)}});
$("#checkSongShow").addEventListener("click", async event => {
  const button = event.currentTarget;
  button.disabled = true;
  try { await loadCatalog(state.selectedId); } finally { button.disabled = false; }
});
$("#runProducerButton").addEventListener("click",runProducer);
$("#producerGrid").addEventListener("click",event=>{const button=event.target.closest("[data-package-status]");if(button)setPackageStatus(button.dataset.packageId,button.dataset.packageStatus)});

loadCatalog();
function renderLyricsSummary(){const input=$("#lyricsText");const summary=$("#lyricsSummary");if(!input||!summary)return;summary.textContent=summarizeLyrics(parseTimestampedLyrics(input.value))}
$("#lyricsText")?.addEventListener("input",renderLyricsSummary);
